with parsed as (select id, created_at, ship_to, attributes, try_cast(attributes['weight_kg'] as double) as weight_kg, exists(items, x -> x.price > 100) as has_premium_item, array_contains(coupon_codes, 'SPRING10') as used_spring10 from carts) select *, last_value(weight_kg, true) over w_part as last_known_weight_kg, count(weight_kg) over (order by cast(created_at as bigint) asc range between 1800 preceding and current row) as weight_kg_count_30m from parsed window w_part as (order by created_at asc, id asc rows between unbounded preceding and current row);
